// Conexão inicial com o SDK do Supabase no frontend ou backend
import { createClient } from '@supabase/supabase-js';

const supabase = createClient(
  process.env.SUPABASE_URL,
  process.env.SUPABASE_ANON_KEY
);

-- Conexão direta SQL com pooling de conexões (porta 6543)
-- postgresql://postgres:[SUA_SENHA]@db.[REF].supabase.co:6543/postgres
CREATE TABLE perfis (
  id UUID PRIMARY KEY REFERENCES auth.users(id),
  nome TEXT NOT NULL
);

// Leitura limpa e fortemente tipada pelo SDK
const { data, error } = await supabase
  .from('produtos')
  .select('id, nome, preco')
  .order('preco', { ascending: false });

if (error) console.error(error.message);

-- Chave primária UUID com geração automática no Postgres
CREATE TABLE tarefas (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  descricao TEXT NOT NULL,
  concluida BOOLEAN DEFAULT false
);

-- O PostgREST detecta a FK e permite queries aninhadas automáticas
CREATE TABLE autores (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  nome TEXT NOT NULL
);

CREATE TABLE livros (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  titulo TEXT NOT NULL,
  autor_id UUID REFERENCES autores(id) ON DELETE CASCADE
);

// Uma tabela 'produtos' no banco se torna acessível imediatamente
// GET https://xyz.supabase.co/rest/v1/produtos?select=id,nome,preco
const { data } = await supabase
  .from('produtos')
  .select('id, nome, preco');

// Operação de atualização (PATCH) segura contra o banco
const { data, error } = await supabase
  .from('usuarios')
  .update({ status: 'ativo' })
  .eq('id', usuarioId);

// Operação de exclusão (DELETE)
await supabase.from('notificacoes').delete().eq('lida', true);

-- Função SQL criada no Postgres para transferência atômica
CREATE OR REPLACE FUNCTION transferir_pontos(remetente UUID, destinatario UUID, qtd INT)
RETURNS VOID AS $$
BEGIN
  UPDATE contas SET pontos = pontos - qtd WHERE id = remetente;
  UPDATE contas SET pontos = pontos + qtd WHERE id = destinatario;
END;
$$ LANGUAGE plpgsql;

// Invocação limpa pelo SDK do Supabase
await supabase.rpc('transferir_pontos', { remetente: '...', destinatario: '...', qtd: 50 });

