    console.log('Nova mensagem recebida:', payload.new);
  })
  .subscribe();

// Ao desmontar: supabase.removeChannel(canal);

// Inscrevendo-se apenas para alterações de um pedido específico
const canal = supabase
  .channel('acompanhamento-pedido')
  .on('postgres_changes', {
    event: 'UPDATE',
    schema: 'public',
    table: 'pedidos',
    filter: 'id=eq.d1b827e6-8c43-4e67-a64d-3b7c3d254e01'
  }, (payload) => {
    console.log('Status atualizado:', payload.new.status);
  })
  .subscribe();

// Enviando coordenadas do cursor para outros membros da sala
const canal = supabase.channel('quadro-branco');
canal.subscribe((status) => {
  if (status === 'SUBSCRIBED') {
    canal.send({
      type: 'broadcast',
      event: 'cursor-pos',
      payload: { x: 140, y: 320, usuario: 'Ana' }
    });
  }
});

// Rastreando presença online em tempo real
const canal = supabase.channel('sala-reuniao');
canal
  .on('presence', { event: 'sync' }, () => {
    const state = canal.presenceState();
    console.log('Usuários online agora:', state);
  })
  .subscribe(async (status) => {
    if (status === 'SUBSCRIBED') {
      await canal.track({ online_at: new Date().toISOString(), usuario: 'Carlos' });
    }
  });

