import { Database } from './types/supabase';
const supabase = createClient<Database>(url, anonKey);
// Agora 'from' e 'select' possuem autocompletion total de tabelas e colunas!

// Tratamento explícito e resiliente do retorno de mutações
const { data, error } = await supabase
  .from('clientes')
  .insert({ nome: 'Marina Santos', email: 'marina@empresa.com' })
  .select()
  .single();

if (error) {
  console.error('Falha ao inserir cliente:', error.message);
  return;
}
console.log('Cliente persistido com sucesso, ID:', data.id);

// Upsert atômico baseado no e-mail único do usuário
const { data, error } = await supabase
  .from('preferencias')
  .upsert({
    usuario_id: userId,
    tema: 'escuro',
    notificacoes_push: true
  }, { onConflict: 'usuario_id' });

// Exemplo de Middleware no Next.js App Router com @supabase/ssr
import { createServerClient } from '@supabase/ssr';
import { NextResponse } from 'next/server';

export async function middleware(req) {
  let res = NextResponse.next();
  const supabase = createServerClient(url, key, {
    cookies: { getAll: () => req.cookies.getAll() }
  });
  const { data: { user } } = await supabase.auth.getUser();
  if (!user && req.nextUrl.pathname.startsWith('/dashboard')) {
    return NextResponse.redirect(new URL('/login', req.url));
  }
  return res;
}

